:root {
  color-scheme: light;
  --bg: #fff;
  --fg: #252525;
  --muted: #777;
  --line: #d5d5d5;
  --soft: #f5f5f5;
  --board: #f4f2ed;
  --grid: #9c9a94;
  --accent: #427363;
  font: 14px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--fg);
  background: transparent;
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #212121;
  --fg: #ececec;
  --muted: #a5a5a5;
  --line: #484848;
  --soft: #2b2b2b;
  --board: #30312e;
  --grid: #74766f;
  --accent: #89bca9;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  background: transparent;
}
main {
  padding: 0;
  max-width: 760px;
  margin-inline: auto;
  background: transparent;
}
button, input {
  font: inherit;
  color: inherit;
}
button {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
  padding: 9px 14px;
  cursor: pointer;
}
button:hover:not(:disabled) {
  background: var(--soft);
}
button:disabled {
  cursor: default;
  opacity: 0.5;
}
button:focus-visible, input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
input {
  border: 1px solid var(--line);
  background: var(--bg);
  border-radius: 8px;
  padding: 8px;
  width: 100px;
}
h2 {
  font-size: 18px;
  font-weight: 600;
  margin: 18px 0 6px;
}
p {
  margin: 6px 0 16px;
}
.muted {
  color: var(--muted);
  font-size: 12px;
}
.toolbar {
  display: flex;
  gap: 6px;
  align-items: center;
}
.phase {
  font-size: 12px;
  color: var(--muted);
}
.spacer {
  flex: 1;
}
.icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  font-size: 20px;
}
.primary {
  background: var(--fg);
  color: var(--bg);
  border-color: var(--fg);
}
.primary:hover:not(:disabled) {
  background: var(--accent);
}

.next {
  display: block;
  margin: 16px auto;
}
.room-lifecycle {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin: 12px auto;
}
.seat-ready-action {
  display: inline-flex;
  width: 30px;
  height: 30px;
  flex: none;
  align-items: center;
  justify-content: center;
  margin-inline-start: 4px;
  padding: 0;
  border-radius: 7px;
}
.seat-ready-icon {
  position: relative;
  width: 16px;
  height: 16px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
}
.seat-ready-action:where([data-ready="true"]) .seat-ready-icon::after {
  position: absolute;
  top: 2px;
  left: 4px;
  width: 4px;
  height: 7px;
  border: solid currentColor;
  border-width: 0 1.5px 1.5px 0;
  content: "";
  transform: rotate(45deg);
}
.seat-ready-action[data-busy="true"] .seat-ready-icon {
  border-style: dashed;
  animation: seat-ready-busy 900ms linear infinite;
}
@keyframes seat-ready-busy {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .seat-ready-action[data-busy="true"] .seat-ready-icon {
    animation: none;
  }
}
.notice {
  text-align: center;
  color: var(--muted);
  font-size: 12px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Shared participant identity inside isolated game surfaces. */
.seat-avatar {
  position: relative;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--soft);
  color: var(--fg);
}
.seat-avatar img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: inherit;
}
.seat-avatar-icon, .seat-avatar-icon svg {
  display: block;
  width: 18px;
  height: 18px;
}
.room-owner {
  position: absolute;
  z-index: 1;
  top: -4px;
  left: -4px;
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  border: 2px solid var(--bg);
  border-radius: 50%;
  background: var(--fg);
  color: var(--bg);
  line-height: 1;
}
.room-owner svg {
  display: block;
  width: 12px;
  height: 12px;
}

